# Locate repository root so tests work under both testthat::test_file() and devtools::test()
find_repo_root <- function() {
  candidates <- c(".", "..", "../..")
  for (cand in candidates) {
    if (file.exists(file.path(cand, "DESCRIPTION")) &&
        file.exists(file.path(cand, "R", "datetimeconverter.b.R"))) {
      return(normalizePath(cand))
    }
  }
  stop("Could not locate ClinicoPathJamoviModule repository root")
}

