# Independent proleptic Gregorian civil-calendar oracle (Howard Hinnant algorithm)
days_from_civil <- function(y, m, d) {
  n_len <- max(length(y), length(m), length(d))
  y <- rep_len(as.integer(y), n_len)
  m <- rep_len(as.integer(m), n_len)
  d <- rep_len(as.integer(d), n_len)
  y_adj <- ifelse(m <= 2L, y - 1L, y)
  era <- ifelse(y_adj >= 0L, y_adj %/% 400L, (y_adj - 399L) %/% 400L)
  yoe <- y_adj - era * 400L
  m_adj <- ifelse(m > 2L, m - 3L, m + 9L)
  doy <- (153L * m_adj + 2L) %/% 5L + d - 1L
  doe <- yoe * 365L + yoe %/% 4L - yoe %/% 100L + doy
  era * 146097L + doe - 719468L
}

oracle_dayofyear <- function(y, m, d) {
  as.integer(days_from_civil(y, m, d) - days_from_civil(y, 1L, 1L) + 1L)
}

oracle_quarter <- function(m) {
  as.integer(((as.integer(m) - 1L) %/% 3L) + 1L)
}

oracle_weeknum <- function(y, m, d) {
  as.integer(((oracle_dayofyear(y, m, d) - 1L) %/% 7L) + 1L)
}

oracle_dayname <- function(y, m, d) {
  z <- days_from_civil(y, m, d)
  w_idx <- ((z + 4L) %% 7L)
  w_idx <- ifelse(w_idx < 0L, w_idx + 7L, w_idx)
  c("Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday")[w_idx + 1L]
}

oracle_epoch_utc <- function(y, m, d, H = 0L, M = 0L, S = 0L) {
  as.numeric(days_from_civil(y, m, d)) * 86400 +
    as.numeric(H) * 3600 + as.numeric(M) * 60 + as.numeric(S)
}

out_vals <- function(output_obj) {
  v <- output_obj$.__enclos_env__$private$.values
  if (is.null(v)) return(NULL)
  unlist(v, use.names = FALSE)
}

out_rows <- function(output_obj) {
  output_obj$.__enclos_env__$private$.rowNums
}

html_text <- function(html_obj) {
  v <- html_obj$content
  if (is.null(v)) "" else paste(as.character(v), collapse = "\n")
}

