test_that("A1: All 12 text formats match exact Hinnant civil-calendar epoch and ISO strings", {
  cases <- list(
    list(fmt = "ymd",    str = c("2024-02-29", "2021-12-31"), H = c(0, 0), M = c(0, 0), S = c(0, 0)),
    list(fmt = "dmy",    str = c("29/02/2024", "31/12/2021"), H = c(0, 0), M = c(0, 0), S = c(0, 0)),
    list(fmt = "mdy",    str = c("02/29/2024", "12/31/2021"), H = c(0, 0), M = c(0, 0), S = c(0, 0)),
    list(fmt = "ydm",    str = c("2024-29-02", "2021-31-12"), H = c(0, 0), M = c(0, 0), S = c(0, 0)),
    list(fmt = "myd",    str = c("02-2024-29", "12-2021-31"), H = c(0, 0), M = c(0, 0), S = c(0, 0)),
    list(fmt = "dym",    str = c("29-2024-02", "31-2021-12"), H = c(0, 0), M = c(0, 0), S = c(0, 0)),
    list(fmt = "ymdhms", str = c("2024-02-29 14:35:09", "2021-12-31 23:59:59"), H = c(14, 23), M = c(35, 59), S = c(9, 59)),
    list(fmt = "dmyhms", str = c("29/02/2024 14:35:09", "31/12/2021 23:59:59"), H = c(14, 23), M = c(35, 59), S = c(9, 59)),
    list(fmt = "mdyhms", str = c("02/29/2024 14:35:09", "12/31/2021 23:59:59"), H = c(14, 23), M = c(35, 59), S = c(9, 59)),
    list(fmt = "ymdhm",  str = c("2024-02-29 14:35", "2021-12-31 23:59"), H = c(14, 23), M = c(35, 59), S = c(0, 0)),
    list(fmt = "dmyhm",  str = c("29/02/2024 14:35", "31/12/2021 23:59"), H = c(14, 23), M = c(35, 59), S = c(0, 0)),
    list(fmt = "mdyhm",  str = c("02/29/2024 14:35", "12/31/2021 23:59"), H = c(14, 23), M = c(35, 59), S = c(0, 0))
  )
  for (tc in cases) {
    res <- dtc_fn(data = data.frame(dt = tc$str), datetime_var = "dt",
                  datetime_format = tc$fmt, timezone = "UTC")
    exp_num <- oracle_epoch_utc(c(2024, 2021), c(2, 12), c(29, 31), tc$H, tc$M, tc$S)
    exp_chr <- sprintf("%04d-%02d-%02d %02d:%02d:%02d", c(2024, 2021), c(2, 12), c(29, 31), tc$H, tc$M, tc$S)
    expect_equal(out_vals(res$corrected_datetime_numeric), exp_num, tolerance = 0, info = tc$fmt)
    expect_identical(out_vals(res$corrected_datetime_char), exp_chr, info = tc$fmt)
  }
})

test_that("A2: Excel 1900 and 1904 serials and all 1440 minutes of a day convert without floating-point drift", {
  mins <- 0:1439
  serials_1440 <- 45306 + mins / 1440
  res_1440 <- dtc_fn(
    data = data.frame(dt = serials_1440), datetime_var = "dt",
    datetime_format = "excel_serial", timezone = "UTC",
    extract_hour = TRUE, extract_minute = TRUE, extract_second = TRUE
  )
  expect_identical(as.integer(out_vals(res_1440$hour_out)),   mins %/% 60L)
  expect_identical(as.integer(out_vals(res_1440$minute_out)), mins %% 60L)
  expect_identical(as.integer(out_vals(res_1440$second_out)), rep(0L, 1440L))

  res_1900 <- dtc_fn(data = data.frame(dt = c(44927, 45351.5)), datetime_var = "dt",
                     datetime_format = "excel_serial", timezone = "UTC")
  res_1904 <- dtc_fn(data = data.frame(dt = c(44927, 45351.5)), datetime_var = "dt",
                     datetime_format = "excel_serial_1904", timezone = "UTC")
  expect_equal(out_vals(res_1904$corrected_datetime_numeric) - out_vals(res_1900$corrected_datetime_numeric),
               rep(1462 * 86400, 2), tolerance = 0)
})

test_that("A3: Unix epoch seconds (including negative pre-1970) and auto-detected milliseconds match exact instants", {
  epochs <- c(-86400, 0, 1709208000, 1735689599)
  res_sec <- dtc_fn(data = data.frame(dt = epochs), datetime_var = "dt",
                    datetime_format = "unix_epoch", timezone = "UTC")
  expect_equal(out_vals(res_sec$corrected_datetime_numeric), epochs, tolerance = 0)
  expect_identical(out_vals(res_sec$corrected_datetime_char),
                   c("1969-12-31 00:00:00", "1970-01-01 00:00:00",
                     "2024-02-29 12:00:00", "2024-12-31 23:59:59"))

  ms <- c(1709208000000, 1735689599000)
  res_ms <- dtc_fn(data = data.frame(dt = ms), datetime_var = "dt",
                   datetime_format = "auto", timezone = "UTC")
  expect_equal(out_vals(res_ms$corrected_datetime_numeric), ms / 1000, tolerance = 0)
})

test_that("A4 & A5: All 11 calendar/clock components and quality metrics match hand-calculated values", {
  df <- data.frame(
    dt = c("2024-02-29 14:35:09", "2020-12-31 23:59:59",
