  expect_identical(as.integer(out_vals(res$year_out)),      c(2024L, 2020L, 2021L, NA_integer_))
  expect_identical(as.integer(out_vals(res$month_out)),     c(2L, 12L, 1L, NA_integer_))
  expect_identical(as.character(out_vals(res$monthname_out)), c("February", "December", "January", NA_character_))
  expect_identical(as.integer(out_vals(res$day_out)),       c(29L, 31L, 1L, NA_integer_))
  expect_identical(as.integer(out_vals(res$hour_out)),      c(14L, 23L, 0L, NA_integer_))
  expect_identical(as.integer(out_vals(res$minute_out)),    c(35L, 59L, 0L, NA_integer_))
  expect_identical(as.integer(out_vals(res$second_out)),    c(9L, 59L, 1L, NA_integer_))
  expect_identical(as.character(out_vals(res$dayname_out)), c("Thursday", "Thursday", "Friday", NA_character_))
  expect_identical(as.integer(out_vals(res$weeknum_out)),   c(9L, 53L, 1L, NA_integer_))
  expect_identical(as.integer(out_vals(res$quarter_out)),   c(1L, 4L, 1L, NA_integer_))
