test_that("C1a-C6: Metamorphic invariants hold for row permutation, NA padding, factor levels, timezone shifts, and two-digit years", {
  set.seed(42)
  perm <- sample(seq_len(nrow(datetimeconverter_test)))
  res_orig <- dtc_fn(data = datetimeconverter_test, datetime_var = "datetime_ymdhms",
                     datetime_format = "auto", timezone = "UTC", extract_dayofyear = TRUE)
  res_perm <- dtc_fn(data = datetimeconverter_test[perm, , drop = FALSE], datetime_var = "datetime_ymdhms",
                     datetime_format = "auto", timezone = "UTC", extract_dayofyear = TRUE)
  expect_identical(out_vals(res_orig$corrected_datetime_numeric)[perm],
                   out_vals(res_perm$corrected_datetime_numeric))

  # Timezone shift equivariance
  str_df <- data.frame(dt = c("2024-01-15 12:00:00", "2024-01-16 12:00:00"))
  res_utc <- dtc_fn(data = str_df, datetime_var = "dt", datetime_format = "ymdhms", timezone = "UTC", extract_hour = TRUE)
  res_ist <- dtc_fn(data = str_df, datetime_var = "dt", datetime_format = "ymdhms", timezone = "Europe/Istanbul", extract_hour = TRUE)
  expect_equal(out_vals(res_ist$corrected_datetime_numeric) - out_vals(res_utc$corrected_datetime_numeric),
               c(-10800, -10800), tolerance = 0)
  expect_identical(as.integer(out_vals(res_ist$hour_out)), c(12L, 12L))

  # Two-digit year rules
  df_2d <- data.frame(dt = c("45-06-15", "68-06-15", "69-06-15"))
  res_std  <- dtc_fn(data = df_2d, datetime_var = "dt", datetime_format = "ymd", two_digit_year = "standard", timezone = "UTC", extract_year = TRUE)
  res_past <- dtc_fn(data = df_2d, datetime_var = "dt", datetime_format = "ymd", two_digit_year = "past", timezone = "UTC", extract_year = TRUE)
  expect_identical(as.integer(out_vals(res_std$year_out)),  c(2045L, 2068L, 1969L))
  expect_identical(as.integer(out_vals(res_past$year_out)), c(1945L, 1968L, 1969L))
})

test_that("D1-D6, E1-E6, H1: Guard boundaries, filtered rownames, option wiring, and HTML XSS escaping hold", {
  # Filtered rownames alignment
  df_5 <- data.frame(dt = c("2024-01-10", "2024-02-20", "2024-03-30", "2024-04-15", "2024-05-25"))
  df_sub <- df_5[c(2, 4, 5), , drop = FALSE]
  res_sub <- dtc_fn(data = df_sub, datetime_var = "dt", datetime_format = "ymd", timezone = "UTC", extract_year = TRUE)
  expect_identical(out_rows(res_sub$corrected_datetime_char), c(2L, 4L, 5L))
  expect_identical(out_rows(res_sub$year_out), c(2L, 4L, 5L))

  # XSS escaping
  xss_df <- data.frame(check.names = FALSE, "<script>alert(1)</script>" = c("2024-01-15", "<img src=x onerror=alert(2)>"))
  res_xss <- suppressWarnings(dtc_fn(
    data = xss_df, datetime_var = "<script>alert(1)</script>",
    datetime_format = "ymd", timezone = "UTC",
    show_quality_metrics = TRUE, show_summary = TRUE
  ))
  all_h <- paste(html_text(res_xss$notices), html_text(res_xss$previewTable),
                 html_text(res_xss$qualityMetrics), html_text(res_xss$nlSummary), collapse = "\n")
  expect_false(grepl("<script>alert(1)</script>", all_h, fixed = TRUE))
  expect_false(grepl("<img src=x onerror=alert(2)>", all_h, fixed = TRUE))
  expect_true(grepl("&lt;script&gt;alert(1)&lt;/script&gt;", all_h, fixed = TRUE))
})

