test_that("VAL-datetimeconverter-02 (S1): Auto-detection is invariant to row order and does not misparse chronologically sorted MM/DD/YYYY or DD/MM/YY columns", {
  dates_mdy <- c(sprintf("01/%02d/2024", rep(1:10, each = 4)), sprintf("01/%02d/2024", 13:31))
  res_asc  <- dtc_fn(data = data.frame(dt = dates_mdy), datetime_var = "dt", datetime_format = "auto", timezone = "UTC")
  res_desc <- dtc_fn(data = data.frame(dt = rev(dates_mdy)), datetime_var = "dt", datetime_format = "auto", timezone = "UTC")
  exp_mdy  <- c(sprintf("2024-01-%02d 00:00:00", rep(1:10, each = 4)), sprintf("2024-01-%02d 00:00:00", 13:31))
  expect_identical(out_vals(res_asc$corrected_datetime_char), exp_mdy)
  expect_identical(out_vals(res_asc$corrected_datetime_char), rev(out_vals(res_desc$corrected_datetime_char)))

  dates_dmy2 <- c(sprintf("%02d/01/21", rep(2:11, each = 4)), sprintf("%02d/01/21", 12:31))
  res_dmy2 <- dtc_fn(data = data.frame(dt = dates_dmy2), datetime_var = "dt", datetime_format = "auto", timezone = "UTC")
  exp_dmy2 <- c(sprintf("2021-01-%02d 00:00:00", rep(2:11, each = 4)), sprintf("2021-01-%02d 00:00:00", 12:31))
  expect_identical(out_vals(res_dmy2$corrected_datetime_char), exp_dmy2)
})

